class V:
    def __init__(self, *a):
        self.a = list(a)

    def __add__(self, o):
        return V(*[x + y for x, y in zip(self.a, o.a)])

    def __len__(self):
        return len(self.a)

    def __repr__(self):
        return f"V{tuple(self.a)}"


print(V(1, 2) + V(3, 4), len(V(1, 2, 3)))
